__NUXT_JSONP__("/svetovy-cas/indie", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{place:[{id:105,tld:".in",name:"Indie",area:3287263,population:1393409038,slug:f,id_continent:c,information_chatgpt:"\u003Cp\u003EIndie je druhým nejlidnatějším státem světa nacházejícím se v Jižní Asii s více než 1,3 miliardami obyvatel. Země má rozmanitou kulturu a bohatou historii sahající až do starověku. Indie je známá svými nádhernými paláci, chrámy a pevnostmi, které přitahují turisty z celého světa. Turisté mohou navštívit města jako Dillí, Mumbaj nebo Jaipur, ale také se podívat na slavnou Tádž Mahal v Agrá nebo na krásné pláže v Goa.\u003C\u002Fp\u003E\n\u003Cp\u003EIndie nabízí také bohatou kuchyni, včetně mnoha vegetariánských pokrmů, a je známá svými exotickými kořenícími směsmi. Nejpopulárnějšími jídly jsou například kari, thali a biryani. Kromě toho je Indie také domovem mnoha trhů, kde můžete nakupovat různé suvenýry, od barevných tkanin po keramiku a šperky.\u003C\u002Fp\u003E\n\u003Cp\u003EIndie má také rozmanitou přírodu, od horských vrcholů v Himálajích až po tropické pláže v jižní části země. Oblast Rádžasthánu nabízí písečné duny a pouště, zatímco na jihu můžete navštívit přírodní rezervaci Perijá, která je domovem vzácných druhů zvířat, jako jsou sloni a tygři. \u003C\u002Fp\u003E\n\u003Cp\u003EIndie má také bohatou literární tradici, ať už se jedná o epos Rámájana a Mahábháratu, nebo moderní literaturu. Země je také známá pro své řemeslné tradice, včetně tkalcovství, keramiky, kovářství a zpracování drahokamů.\u003C\u002Fp\u003E\n\u003Cp\u003EIndie je fascinující země s mnoha zajímavými místy a zážitky pro turisty. Pokud plánujete návštěvu, je důležité být obeznámen s místními zvyky a tradicemi a být připraven na některé kulturní rozdíly.\u003C\u002Fp\u003E",currency_code:"INR",currency_name:"rupie",money_prices:[{name:"Taxi (cena za km)",value:d,date_update:a},{name:"Hlavní jídlo",value:g,date_update:a},{name:"Chleba",value:d,date_update:a},{name:"Mléko",value:h,date_update:a},{name:"Voda (500ml)",value:15,date_update:a},{name:"Espresso",value:60,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:d,date_update:a},{name:"Pivo",value:g,date_update:a},{name:"Krabička cigaret",value:250,date_update:a},{name:"Bic Mac",value:220,date_update:a},{name:"Coca Cola (500ml)",value:d,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:a},{name:"Policie",value:"100",date_update:a},{name:"Hasiči",value:"101",date_update:a},{name:"Zdravotnická záchranná služba",value:"102",date_update:a}],phone_prefix:"+91",coordinates:[{latitude:"20.5937",longitude:"78.9629"}],people_religion:[{name:"Hinduismus",value:i},{name:"Islám",value:j},{name:"Křesťanství",value:k},{name:"Sikhismus",value:l},{name:"Buddhismus",value:m},{name:"Jiná náboženství",value:n},{name:"Bez vyznání",value:"0.4%"}],people_nationality:[{name:"Hindové",value:i},{name:"Muslimové",value:j},{name:"Křesťané",value:k},{name:"Sikhowé",value:l},{name:"Buddhisté",value:m},{name:"Jiní",value:n}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Indie je potřeba mít platný cestovní doklad. Pokud jste občanem ČR a plánujete zůstat v Indii do 90 dnů, můžete vstoupit pouze s platným občanským průkazem.",date_update:a},{name:"Cestovní pas",value:"Pro vstup do Indie je potřeba mít platný cestovní pas. Pokud plánujete zůstat v Indii déle než 90 dnů, budete potřebovat vízum a tedy i pas.",date_update:a},{name:"Vízum",value:"Pro vstup do Indie je potřeba mít vízum. Občané ČR mohou využít elektronického víza (eVisa), které platí pro turistické a obchodní účely a umožňuje pobyt v zemi maximálně 60 dnů. Pro delší pobyt je potřeba vyřídit vízum přímo u indického velvyslanectví.",date_update:a},{name:"Očkování",value:"Při vstupu do Indie nejsou povinná žádná očkování, nicméně jsou doporučována následující: očkování proti žluté zimnici (pokud cestujete z nakažené oblasti), očkování proti hepatitidě A a B, očkování proti tyfu, očkování proti japonecké encefalitidě (pokud cestujete do oblastí, kde se vyskytuje), očkování proti klíšťové encefalitidě (pokud cestujete do oblastí, kde se vyskytuje).",date_update:a},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné, ale silně se doporučuje mít ho uzavřené, protože zdravotní péče v Indii může být velmi drahá.",date_update:a},{name:"Bezpečnostní situace",value:"V Indii existuje vysoké riziko teroristických útoků, násilné kriminality, korupce a demonstrací. Turisté by měli být obezřetní a informovat se o aktuální situaci před cestou.",date_update:a},{name:"Další informace",value:"Při návštěvě chrámů a jiných náboženských míst je třeba dodržovat zvyklosti, jako například zakrývání ramen a nohou, a neporušovat náboženská pravidla. Dále je třeba dbát na hygienu a vyhýbat se neupraveným potravinám a vodě.",date_update:a}],type_place:o,id_image_cover:e,id_image_hero:e,id_city_main:1019,affiliate:[{name:"booking",value:true}],mpz:"IN",alerts:b,zoom:[{google:p,booking:p}],ids_neighboring_countries:b,organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b}],imagePlace:[{id:e,name:f,source:"\u002Fworld\u002Fstates\u002F",date_create:"2023-05-02T18:49:47.851894+00:00",type:o,author:"pixabay.com"}],placeContinent:[{id:c,slug:"asie",name:"Asie",area:44580000,population:4630000000,population_density:104.03,number_states:h,information_chatgpt:"\u003Cp\u003EAsie se rozkládá na ploše téměř 44,6 milionu kilometrů čtverečních a žije zde více než 4,5 miliardy lidí, což představuje téměř 60 % celkového počtu obyvatel planety. Kontinent zahrnuje celkem 48 zemí, mezi největší patří Rusko, Čína, Indie, Japonsko a Indonésie.\u003C\u002Fp\u003E\n\u003Cp\u003EAsie je domovem mnoha významných světových kultur, jako jsou hinduismus, buddhismus, islám a taoismus. V každé zemi se můžeš setkat s odlišnými tradicemi, zvyky a jazyky. Mezi nejnavštěvovanější turistické destinace patří například Japonsko s jeho futuristickými městy, Thajsko s bohatou kulturou a krásnými plážemi, nebo Indonésie s neuvěřitelnou přírodou a množstvím ostrovů.\u003C\u002Fp\u003E\n\u003Cp\u003EAsie také nabízí mnoho kulturních a historických památek, jako je Velká čínská zeď, Taj Mahal v Indii, buddhistické chrámy v Thajsku a mnoho dalšího. Zajímavou zkušeností může být i návštěva tradičních trhů, kde se dají ochutnat místní speciality a nakoupit různé exotické produkty.\u003C\u002Fp\u003E\n\u003Cp\u003EAsie má však také své výzvy a problémy, jako jsou například růst městských oblastí, nedostatek vody a znečištění ovzduší. Mnoho zemí se snaží najít řešení těchto problémů a přizpůsobit se moderním trendům, aby mohly udržet krok s ostatními zeměmi světa.\u003C\u002Fp\u003E\n\u003Cp\u003EPokud tě láká cestování po Asii, měl by sis předem zajistit víza a informovat se o místních zvycích a tradicích. Rozhodně se ti však naskytne možnost prozkoumat jedinečnou kulturu, přírodu a historii tohoto fascinujícího kontinentu.\u003C\u002Fp\u003E\u003Cp\u003EAsie má také neuvěřitelně bohatou gastronomii, která se v jednotlivých zemích a regionech liší. Mezi nejznámější asijské pokrmy patří sushi, různé druhy nudlí, curry, dim sum, pho a další. Kromě toho se v Asii pěstuje mnoho exotických plodin, jako jsou duriany, mangostany, rambutany a další ovoce, které můžeš ochutnat pouze zde.\n\u003C\u002Fp\u003E\u003Cp\u003E\nAsie je také známá svými svátky a tradicemi, jako je například čínský Nový rok, Diwali v Indii, nebo Songkran v Thajsku. Tyto svátky jsou většinou spojeny s různými rituály a zvyky, které se v průběhu staletí vyvinuly a jsou dodnes respektovány.\n\u003C\u002Fp\u003E\u003Cp\u003E\nKromě toho má Asie mnoho přírodních krás, jako jsou Himálaje, pouště Gobi a Thar, nebo tropické pralesy v Indonésii a Malajsii. V Asii se také nachází mnoho národních parků a chráněných oblastí, kde žijí ohrožené druhy zvířat, jako jsou tygři, pandy, sloni a další.\n\u003C\u002Fp\u003E\u003Cp\u003E\nZkrátka, Asie je kontinent plný kontrastů a neuvěřitelných zážitků, které stojí za to objevovat. Budeš-li mít příležitost navštívit některou z asijských zemí, neváhej a vydaj se na dobrodružnou cestu plnou nových objevů a nezapomenutelných zážitků.\u003C\u002Fp\u003E",coordinates:[{latitude:47.751076,longitude:92.475286}],type_place:"continent",id_image_cover:c,id_image_hero:c,zoom:[{google:2,booking:c}],information_author:b,seo_tags:b}]}],fetch:{},mutations:void 0}}("05-2023",null,3,20,268,"indie",150,50,"79.8%","14.2%","2.3%","1.7%","0.7%","0.9%","state",4)));